using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Web.Script.Serialization;using interop.ICApiIronCAD;
namespace RockPro{public static class LatchInProcess{
public static int Run(string folder){var j=new JavaScriptSerializer{MaxJsonLength=64000000};var r=new Dictionary<string,object>();try{var q=(Dictionary<string,object>)j.DeserializeObject(File.ReadAllText(Path.Combine(folder,"request.json")));if(System.Diagnostics.Process.GetCurrentProcess().Id!=Convert.ToInt32(q["expected_pid"]))throw new Exception("Host changed");dynamic l=Marshal.GetActiveObject("IronCAD.Application");var a=(IZBaseApp)l.ZIronCADApp;var d=a.ActiveDoc;var s=(IZSceneDoc)d;var u=(IZSceneDocUtility)s;r["document"]=d.Name;r["active_config"]=s.ConfigurationMgr.ActiveConfiguration.Name;r["default_config"]=s.ConfigurationMgr.DefaultConfiguration.Name;r["configs"]=((Array)s.ConfigurationMgr.GetConfigurations()).Cast<object>().Select(x=>{var c=(IZConfiguration)x;return new{name=c.Name,active=c.IsActive,def=c.IsDefault,suppression=c.DefaultSuppressionState,position=c.StorePosition};}).ToArray();var rows=new List<object>();var ids=(Dictionary<string,object>)q["part_id_map"];foreach(int id in new[]{115,116,174,178,179,183,195,200}){var e=u.GetElementById(ids.ContainsKey(id.ToString())?Convert.ToInt32(ids[id.ToString()]):id);var states=Enum.GetValues(typeof(eZElementState)).Cast<eZElementState>().ToDictionary(k=>k.ToString(),k=>e.GetStateStatus(k));var featureStates=new List<object>();if(e.Type==eZElementType.Z_ELEMENT_PART){var mgr=(IZPartFeatureMgr)e;for(int i=0;i<mgr.GetFeaturesCount();i++){var f=(IZElement)mgr.GetFeatureAt(i);featureStates.Add(new{id=f.Id,name=f.Name,suppressed=f.GetStateStatus(eZElementState.Z_SUPPRESSED),hidden=f.GetStateStatus(eZElementState.Z_HIDDEN)});}}rows.Add(new{id=e.Id,name=e.Name,states=states,features=featureStates});}r["rows"]=rows;r["passed"]=true;}catch(Exception ex){r["error"]=ex.ToString();r["passed"]=false;}File.WriteAllText(Path.Combine(folder,"result.json"),j.Serialize(r));return(bool)r["passed"]?0:1;}
}}
